// === CONFIG CLOUD API — Roteamento de Phone Number ID ===
// Resolve phone_number_id + token por agent_id.
// BM API 1 (WABA do expert) — numero (numero do expert).

const PHONE_NUMBER_MAP = {
  'default': '{{PHONE_NUMBER_ID}}',
  'bia': '{{PHONE_NUMBER_ID}}',
  'bia-convite': '{{PHONE_NUMBER_ID}}',
  'bia-recovery': '{{PHONE_NUMBER_ID}}',
  'bia-boas-vindas': '{{PHONE_NUMBER_ID}}',
};

// Token System User da BM API 1
// PLACEHOLDER — substituir com o token real da sua API Meta (pré-requisito)
// Token POR NUMERO. 1 BM = 1 token (deixe so o primario abaixo).
// Varios numeros de BMs DIFERENTES = adicione 1 linha por numero (pnid: token).
const TOKEN_BY_PHONE = {
  '{{PHONE_NUMBER_ID}}': '{{SYSTEM_USER_TOKEN}}',
  // '<phone_number_id_2>': '<system_user_token_2>',
};

const input = $input.first().json;
const agent_id = input.agent_id || 'bia';
const phone_number_id = input.phone_number_id || PHONE_NUMBER_MAP[agent_id] || PHONE_NUMBER_MAP['default'];
const CLOUD_API_TOKEN = TOKEN_BY_PHONE[phone_number_id] || '{{SYSTEM_USER_TOKEN}}';

return [{ json: {
  ...input,
  phone_number_id,
  cloud_api_token: CLOUD_API_TOKEN,
  graph_api_url: 'https://graph.facebook.com/v21.0/' + phone_number_id
} }];

// === CHECK ATENDIMENTO HUMANO — Cloud API Edition ===
// Verifica is_human_takeover na tabela bia_whatsapp_contacts (Supabase).
// Se humano atendendo, NAO envia resposta IA.
// Se agent_id especifico (pipeline ativa), SEMPRE envia.

const https = require('https');

const SUPA_HOST = '{{SUPABASE_PROJECT_REF}}.supabase.co';
const SUPA_KEY = '{{SUPABASE_SERVICE_ROLE_KEY}}';

function supaGet(path) {
  return new Promise((resolve, reject) => {
    const options = {
      hostname: SUPA_HOST,
      path: '/rest/v1/' + path,
      method: 'GET',
      headers: {
        'apikey': SUPA_KEY,
        'Authorization': 'Bearer ' + SUPA_KEY
      },
      timeout: 5000
    };
    const req = https.request(options, (res) => {
      let data = '';
      res.on('data', c => data += c);
      res.on('end', () => {
        try { resolve(JSON.parse(data)); }
        catch { resolve([]); }
      });
    });
    req.on('timeout', () => { req.destroy(); reject({ code: 'ETIMEDOUT' }); });
    req.on('error', reject);
    req.end();
  });
}

const input = $input.first().json;
const phone = input.phone;

// Se agent_id especifico (pipeline ativa), sempre envia
if (input.agent_id && input.agent_id !== 'bia') {
  return [{ json: { ...input, _skip: false } }];
}

// Verifica flag humano no Supabase
try {
  const contacts = await supaGet(
    'bia_whatsapp_contacts?phone=eq.' + encodeURIComponent(phone) + '&select=is_human_takeover'
  );
  if (contacts.length > 0 && contacts[0].is_human_takeover) {
    return [{ json: { _skip: true, reason: 'humano_atendendo', phone } }];
  }
} catch (e) {
  // Se check falhar, segue normalmente (nao bloqueia pipeline)
}

return [{ json: { ...input, _skip: false } }];

// === CHUNKER — Portado do David (Separa Frases) ===
// Algoritmo original preservado integralmente
// Preserva: links, R$, parenteses, emails

const input = $input.first().json;
// === HANDOFF_HUMANO Detection ===
const rawText = input.resposta_final || input.resposta || '';
const needsHandoff = rawText.includes('[HANDOFF_HUMANO]');
const cleanText = rawText.replace(/\[HANDOFF_HUMANO\]/g, '').trim();
// Override resposta with cleaned version
const resposta = cleanText;

if (!resposta.trim()) {
  return [{ json: { needs_handoff: needsHandoff, ...input, chunks: [], total_chunks: 0 } }];
}

// Funcao para remover citacoes no formato 【...】
function removeCitations(text) {
  return text.replace(/【[^】]*】/g, '').trim();
}

// Funcao para identificar links e e-mails
function isLinkOrEmail(text) {
  const urlRegex = /^(https?:\/\/)?[\w.-]+\.[a-z]{2,}(\/\S*)?$/i;
  const emailRegex = /\S+@\S+\.\S+/;
  return urlRegex.test(text.trim()) || emailRegex.test(text.trim());
}

// Funcao para verificar se e um numero com pontuacao
function isNumberWithPunctuation(text) {
  return /^[\d.,/-]+$/.test(text.trim());
}

// Funcao para verificar se a palavra termina com pontuacao de fim de frase
function endsWithSentencePunctuation(word) {
  return word.endsWith('.') || word.endsWith('?') || word.endsWith('!');
}

// Funcao principal de split — PORTADA INTEGRALMENTE do David
function splitTextPreservingSpecialCases(text) {
  const parts = [];
  let currentPart = '';
  let insideParentheses = false;
  const words = text.split(/\s+/);

  for (let i = 0; i < words.length; i++) {
    const word = words[i];

    if (word.includes('(')) insideParentheses = true;

    if (isLinkOrEmail(word)) {
      if (currentPart.trim()) {
        parts.push(currentPart.trim());
        currentPart = '';
      }
      parts.push(word);
    } else if (isNumberWithPunctuation(word) || insideParentheses || (word === 'R$' && i < words.length - 1 && isNumberWithPunctuation(words[i + 1]))) {
      currentPart += (currentPart ? ' ' : '') + word;
    } else {
      currentPart += (currentPart ? ' ' : '') + word;
      if (endsWithSentencePunctuation(word) && !insideParentheses) {
        parts.push(currentPart.trim());
        currentPart = '';
      }
    }

    if (word.includes(')')) {
      insideParentheses = false;
      if (endsWithSentencePunctuation(word)) {
        parts.push(currentPart.trim());
        currentPart = '';
      }
    }
  }

  if (currentPart.trim()) {
    parts.push(currentPart.trim());
  }

  return parts;
}

// Executa
let cleanedText = removeCitations(resposta);

// STEP 1: Split by line breaks FIRST (cada \n = mensagem separada)
const lineChunks = cleanedText.split(/\n+/).map(l => l.trim()).filter(l => l.length > 0);

// STEP 2: Apply sentence-based splitting WITHIN each line (ALWAYS)
let chunks = [];
for (const line of lineChunks) {
  const subChunks = splitTextPreservingSpecialCases(line);
  chunks.push(...subChunks);
}

// Limite de 15 chunks — agrupa excedentes no ultimo
const MAX_CHUNKS = 15;
if (chunks.length > MAX_CHUNKS) {
  const excess = chunks.slice(MAX_CHUNKS - 1).join(' ');
  chunks = chunks.slice(0, MAX_CHUNKS - 1);
  chunks.push(excess);
}

// Calcula delay por chunk baseado no tamanho
// Delay fixo de 3.2s entre chunks (calibrado em producao)
const chunksWithDelay = chunks.map((text, i) => {
  return { text, delay_ms: 3200, index: i + 1 };
});

return [{
  json: {
    subscriber_id: input.subscriber_id,
    nome: input.nome,
    handoff: input.handoff || false,
    needs_handoff: needsHandoff,
    chunks: chunksWithDelay,
    total_chunks: chunksWithDelay.length,
    llm_provider: input.llm_provider,
    llm_model: input.llm_model,
    tokens_in: input.tokens_in,
    tokens_out: input.tokens_out
  }
}];

// === SENDER CLOUD API v1.0 ===
// Envia chunks via Graph API POST (Phone Number ID {{PHONE_NUMBER_ID}}).
// Sync outbound → Chatwoot (CRM/monitor only).
// Handoff: flag Supabase + Chatwoot open + SMS/WhatsApp Twilio.

const https = require('https');

function httpRequest(method, hostname, path, headers, body) {
  return new Promise((resolve, reject) => {
    const bodyStr = body ? (typeof body === 'string' ? body : JSON.stringify(body)) : '';
    const reqHeaders = { ...headers };
    if (body) reqHeaders['Content-Length'] = Buffer.byteLength(bodyStr);
    const options = { hostname, path, method, headers: reqHeaders, timeout: 15000, rejectUnauthorized: false };
    const req = https.request(options, (res) => {
      let data = '';
      res.on('data', chunk => data += chunk);
      res.on('end', () => {
        try { resolve({ ok: res.statusCode >= 200 && res.statusCode < 300, status: res.statusCode, data: JSON.parse(data) }); }
        catch { resolve({ ok: res.statusCode >= 200 && res.statusCode < 300, status: res.statusCode, data: { raw: data } }); }
      });
    });
    req.on('timeout', () => { req.destroy(); reject({ code: 'ETIMEDOUT' }); });
    req.on('error', (e) => resolve({ ok: false, status: 0, data: { error: e.message } }));
    if (body) req.write(bodyStr);
    req.end();
  });
}

function httpPostForm(hostname, path, authHeader, formParams) {
  return new Promise((resolve, reject) => {
    const bodyStr = Object.entries(formParams)
      .map(([k, v]) => encodeURIComponent(k) + '=' + encodeURIComponent(v))
      .join('&');
    const options = {
      hostname, path, method: 'POST',
      headers: {
        'Authorization': authHeader,
        'Content-Type': 'application/x-www-form-urlencoded',
        'Content-Length': Buffer.byteLength(bodyStr)
      }
    };
    const req = https.request(options, (res) => {
      let data = '';
      res.on('data', chunk => data += chunk);
      res.on('end', () => {
        try { resolve({ ok: res.statusCode >= 200 && res.statusCode < 300, data: JSON.parse(data) }); }
        catch { resolve({ ok: res.statusCode >= 200 && res.statusCode < 300, data: { raw: data } }); }
      });
    });
    req.on('error', (e) => resolve({ ok: false, data: { error: e.message } }));
    req.write(bodyStr);
    req.end();
  });
}

const input = $input.first().json;
const triggerData = (() => { try { return $('Execute Workflow Trigger').first().json; } catch { return input; } })();
const config = (() => { try { return $('Config Cloud API').first().json; } catch { return input; } })();

const chunks = input.chunks || [];
const phone = triggerData.phone || input.phone || triggerData.subscriber_id || input.subscriber_id;
const phone_number_id = config.phone_number_id;
const token = config.cloud_api_token;
const subscriber_id = triggerData.subscriber_id || input.subscriber_id || phone;

// Chatwoot config
const CHATWOOT_HOST = 'chatwoot.{{SEU_DOMINIO}}';
const CHATWOOT_TOKEN = '{{CHATWOOT_TOKEN}}';
// Resolve chatwoot_conversation_id — fallback: Supabase lookup
let chatwoot_conversation_id = triggerData.chatwoot_conversation_id || input.chatwoot_conversation_id;
if (!chatwoot_conversation_id && phone) {
  try {
    const cwLookup = await httpRequest('GET', SUPA_HOST,
      '/rest/v1/bia_whatsapp_contacts?phone=eq.' + phone + '&select=chatwoot_conversation_id',
      { 'apikey': SUPA_KEY, 'Authorization': 'Bearer ' + SUPA_KEY });
    if (cwLookup.ok && Array.isArray(cwLookup.data) && cwLookup.data.length > 0 && cwLookup.data[0].chatwoot_conversation_id) {
      chatwoot_conversation_id = cwLookup.data[0].chatwoot_conversation_id;
    }
  } catch (e) { /* fallback failed, continue without sync */ }
}

// Supabase config
const SUPA_HOST = '{{SUPABASE_PROJECT_REF}}.supabase.co';
const SUPA_KEY = '{{SUPABASE_SERVICE_ROLE_KEY}}';

if (chunks.length === 0) {
  return [{ json: { status: 'no_chunks', phone, subscriber_id } }];
}

const results = [];


// Delay inicial 2.7s — simula Bia "lendo" antes de responder
await new Promise(r => setTimeout(r, 2700));

for (let i = 0; i < chunks.length; i++) {
  const chunk = chunks[i];

  // Delay humanizado entre chunks (3.2s)
  if (i > 0) await new Promise(r => setTimeout(r, chunk.delay_ms));

  // Envia via Cloud API (Graph API)
  try {
    const res = await httpRequest('POST', 'graph.facebook.com',
      '/v21.0/' + phone_number_id + '/messages',
      { 'Authorization': 'Bearer ' + token, 'Content-Type': 'application/json' },
      { messaging_product: 'whatsapp', to: phone, type: 'text', text: { body: chunk.text } }
    );

    if (res.ok) {
      results.push({ chunk: i + 1, status: 'sent', wamid: (res.data.messages || [])[0]?.id });
    } else {
      results.push({ chunk: i + 1, status: 'error', code: res.status, error: JSON.stringify(res.data).substring(0, 200) });
    }
  } catch (e) {
    results.push({ chunk: i + 1, status: 'error', error: e.message });
  }

  // Sync outbound → Chatwoot (best effort)
  if (chatwoot_conversation_id) {
    try {
      await httpRequest('POST', CHATWOOT_HOST,
        '/api/v1/accounts/2/conversations/' + chatwoot_conversation_id + '/messages',
        { 'api_access_token': CHATWOOT_TOKEN, 'Content-Type': 'application/json' },
        { content: chunk.text + '\u200B', message_type: 'outgoing', private: false, content_attributes: { external: true, synced_by: 'n8n' } }
      );
    } catch (e) { /* best effort */ }
  }
}

// Handle handoff
const needs_handoff = input.needs_handoff || false;
if (triggerData.handoff || needs_handoff) {
  // 1. Flag Supabase: is_human_takeover = true
  try {
    await httpRequest('PATCH', SUPA_HOST,
      '/rest/v1/bia_whatsapp_contacts?phone=eq.' + encodeURIComponent(phone),
      {
        'Content-Type': 'application/json',
        'apikey': SUPA_KEY,
        'Authorization': 'Bearer ' + SUPA_KEY,
        'Prefer': 'return=minimal'
      },
      { is_human_takeover: true }
    );
    results.push({ action: 'supabase_handoff_flag', status: 'ok' });
  } catch (e) {
    results.push({ action: 'supabase_handoff_flag', status: 'error', error: e.message });
  }

  // 2. Chatwoot: abrir conversa (status open)
  if (chatwoot_conversation_id) {
    try {
      await httpRequest('PATCH', CHATWOOT_HOST,
        '/api/v1/accounts/2/conversations/' + chatwoot_conversation_id + '/toggle_status',
        { 'api_access_token': CHATWOOT_TOKEN, 'Content-Type': 'application/json' },
        { status: 'open' }
      );
      results.push({ action: 'chatwoot_open', status: 'ok' });
    } catch (e) {
      results.push({ action: 'chatwoot_open', status: 'error', error: e.message });
    }
  }

  // 3. SMS + WhatsApp suporte via Twilio
  const TWILIO_SID = '{{TWILIO_ACCOUNT_SID}}';
  const TWILIO_TOKEN = '{{TWILIO_AUTH_TOKEN}}';
  const TWILIO_AUTH = 'Basic ' + Buffer.from(TWILIO_SID + ':' + TWILIO_TOKEN).toString('base64');
  const TWILIO_FROM = '{{TWILIO_FROM_NUMBER}}';
  const SUPORTE_ALERTA = '+{{WHATSAPP_SUPORTE}}';

  let mensagem = 'N/A';
  try { mensagem = triggerData.mensagem || input.mensagem_original || 'N/A'; } catch (e) {}
  const notifMsg = 'HANDOFF [Cloud API]: Lead ' + (triggerData.nome || input.nome || phone) + '\nMsg: ' + mensagem;

  try {
    await Promise.allSettled([
      httpPostForm('api.twilio.com', '/2010-04-01/Accounts/' + TWILIO_SID + '/Messages.json',
        TWILIO_AUTH, { From: TWILIO_FROM, To: SUPORTE_ALERTA, Body: notifMsg }),
      httpPostForm('api.twilio.com', '/2010-04-01/Accounts/' + TWILIO_SID + '/Messages.json',
        TWILIO_AUTH, { From: 'whatsapp:' + TWILIO_FROM, To: 'whatsapp:' + SUPORTE_ALERTA, Body: notifMsg })
    ]);
    results.push({ action: 'twilio_notify', status: 'ok' });
  } catch (e) {
    results.push({ action: 'twilio_notify', status: 'error', error: e.message });
  }

  // 4. Registra handoff no Supabase (bia_handoffs)
  try {
    await httpRequest('POST', SUPA_HOST, '/rest/v1/bia_handoffs',
      {
        'Content-Type': 'application/json',
        'apikey': SUPA_KEY,
        'Authorization': 'Bearer ' + SUPA_KEY,
        'Prefer': 'return=minimal'
      },
      {
        subscriber_id: String(subscriber_id),
        subscriber_name: triggerData.nome || input.nome || null,
        phone: phone,
        agent_id: triggerData.agent_id || input.agent_id || 'bia',
        reason: needs_handoff ? 'handoff_ia' : 'handoff_trigger',
        status: 'aberto'
      }
    );
    results.push({ action: 'supabase_handoff_logged', status: 'ok' });
  } catch (e) {
    results.push({ action: 'supabase_handoff_logged', status: 'error', error: e.message });
  }
}

const sent_count = results.filter(r => r.status === 'sent').length;

return [{ json: {
  subscriber_id,
  nome: triggerData.nome || input.nome,
  phone,
  total_chunks_sent: sent_count,
  total_chunks: chunks.length,
  handoff: triggerData.handoff || false,
  needs_handoff,
  delivery_method: 'cloud_api_direct',
  results
} }];

// === LOG INTERACAO — Cloud API Edition (versao kit) ===
// Log estruturado + daily stats em memoria. Sem dependencias externas.

const input = $input.first().json;
const sd = $getWorkflowStaticData('node');

const logEntry = {
  ts: new Date().toISOString(),
  phone: input.phone || input.subscriber_id,
  nome: input.nome || 'Lead',
  agent_id: input.agent_id || 'bia',
  llm: input.llm_provider || 'unknown',
  model: input.llm_model || 'unknown',
  tok_in: input.tokens_in || 0,
  tok_out: input.tokens_out || 0,
  chunks_sent: input.total_chunks_sent || 0,
  chunks_total: input.total_chunks || 0,
  handoff: input.handoff || false,
  needs_handoff: input.needs_handoff || false,
  source: 'cloud_api',
  status: 'ok'
};

if (input.handoff || input.needs_handoff) logEntry.status = 'handoff';
else if ((input.total_chunks || 0) > 0 && (input.total_chunks_sent || 0) === 0) logEntry.status = 'delivery_error';
else if ((input.total_chunks_sent || 0) > 0 && input.total_chunks_sent < input.total_chunks) logEntry.status = 'partial';

// === Daily stats (em memoria, sem dependencia externa) ===
const today = logEntry.ts.split('T')[0];
if (!sd.daily) sd.daily = {};
if (!sd.daily[today]) sd.daily[today] = { total: 0, errors: 0, handoffs: 0, fallbacks: 0, tokens_in: 0, tokens_out: 0 };
const d = sd.daily[today];
d.total++;
d.tokens_in += logEntry.tok_in;
d.tokens_out += logEntry.tok_out;
if (logEntry.status === 'delivery_error' || logEntry.status === 'partial') d.errors++;
if (logEntry.status === 'handoff') d.handoffs++;
if (input.was_fallback) d.fallbacks++;

const cutoff = new Date(); cutoff.setDate(cutoff.getDate() - 30);
const cutoffStr = cutoff.toISOString().split('T')[0];
for (const day of Object.keys(sd.daily)) { if (day < cutoffStr) delete sd.daily[day]; }

console.log('[WF-OUTBOUND-CLOUD]', JSON.stringify(logEntry));

return [{ json: { ...input, log: logEntry, daily_stats: sd.daily[today] } }];
